cat > /app/output/styles.css <<'EOF'
:root {
  --bg: #f8fbff;
  --surface: #ffffff;
  --text: #0f172a;
  --muted: #4b5563;
  --primary: #1e40ff;
  --primary-2: #312e81;
  --accent: #ff5f52;
  --accent-2: #23d57d;
  --ring: rgba(30, 64, 255, 0.2);
  --shadow: 0 12px 32px rgba(15, 23, 42, 0.08);
  --radius: 18px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: var(--text);
  background:
    radial-gradient(circle at 0% 0%, #dce7ff 0, transparent 34%),
    radial-gradient(circle at 100% 10%, #dcfff0 0, transparent 24%),
    var(--bg);
  line-height: 1.6;
}
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image: radial-gradient(rgba(15,23,42,.08) .6px, transparent .6px);
  background-size: 3px 3px;
  opacity: .08;
  pointer-events: none;
  z-index: -1;
}
.container { width: min(1180px, 92vw); margin: 0 auto; }
.section { padding: 78px 0; }
h1, h2, h3 { font-family: 'Satoshi', 'Space Grotesk', 'Plus Jakarta Sans', sans-serif; line-height: 1.08; letter-spacing: -.02em; margin: 0 0 14px; }
h1 { font-size: clamp(2.2rem, 4.6vw, 4.5rem); }
h2 { font-size: clamp(1.8rem, 3.2vw, 3rem); }
h3 { font-size: clamp(1.2rem, 2vw, 1.6rem); }
p { margin: 0 0 14px; color: var(--muted); }
.small { font-size: .94rem; }
.kicker { display: inline-flex; align-items: center; gap: 8px; border-radius: 999px; background: #e7edff; color: var(--primary-2); font-weight: 700; font-size: .78rem; padding: 7px 12px; margin-bottom: 18px; }
.nav-wrap { position: sticky; top: 0; z-index: 40; backdrop-filter: blur(10px); background: rgba(248,251,255,.8); border-bottom: 1px solid #e7eaf5; }
.nav { display: flex; align-items: center; justify-content: space-between; padding: 14px 0; gap: 16px; }
.logo { display: flex; align-items: center; gap: 10px; text-decoration: none; color: var(--text); font-family: 'Satoshi', sans-serif; font-weight: 900; font-size: 1.1rem; }
.logo-mark { width: 34px; height: 34px; border-radius: 10px; background: linear-gradient(135deg, var(--primary), var(--accent)); box-shadow: 0 6px 16px rgba(30,64,255,.3); }
.nav-links { display: flex; gap: 18px; flex-wrap: wrap; }
.nav-links a { color: #1f2937; text-decoration: none; font-weight: 600; font-size: .92rem; }
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; border-radius: 12px; padding: 12px 18px; font-weight: 700; text-decoration: none; border: 1px solid transparent; transition: .25s ease; }
.btn-primary { background: linear-gradient(135deg, var(--primary), #3654ff); color: #fff; box-shadow: 0 10px 24px rgba(30,64,255,.28); }
.btn-primary:hover { transform: translateY(-2px); }
.btn-ghost { border-color: #d7ddf3; color: var(--text); background: #fff; }
.hero { padding: 72px 0 26px; }
.hero-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 28px; align-items: center; }
.card { background: var(--surface); border: 1px solid #e8ecf7; border-radius: var(--radius); box-shadow: var(--shadow); }
.hero-panel { padding: 22px; }
.tab-switch { display: inline-flex; border: 1px solid #dce2f3; border-radius: 12px; overflow: hidden; }
.tab-switch button { border: 0; background: #f4f7ff; padding: 10px 14px; font-weight: 700; cursor: pointer; }
.tab-switch button.active { background: var(--primary); color: #fff; }
.preview { margin-top: 16px; padding: 16px; border-radius: 14px; background: #f7f9ff; border: 1px solid #e2e8f8; min-height: 220px; }
.preview.hidden { display: none; }
.stats { margin-top: 26px; display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; }
.stat { padding: 18px; border-radius: 14px; background: #fff; border: 1px solid #e7eaf5; text-align: center; }
.stat strong { display: block; color: var(--primary-2); font-size: clamp(1.4rem,2.3vw,2rem); }
.grid-4 { display: grid; grid-template-columns: repeat(4,1fr); gap: 16px; }
.grid-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }
.feature-card { padding: 20px; }
.tabs { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }
.tabs button { border: 1px solid #d9dff2; background: #fff; border-radius: 12px; padding: 10px 12px; font-weight: 700; cursor: pointer; }
.tabs button.active { background: #e9edff; border-color: #b9c6ff; color: var(--primary-2); }
.tab-panel { display: none; }
.tab-panel.active { display: block; }
.logo-grid { display: grid; grid-template-columns: repeat(6,1fr); gap: 12px; }
.logo-item { border: 1px solid #e4e8f6; border-radius: 12px; background: #fff; padding: 15px; font-weight: 700; text-align: center; color: #24304f; }
.pricing { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }
.price-card { padding: 22px; }
.price { font-size: 2rem; color: var(--primary-2); font-weight: 900; }
.carousel { position: relative; }
.carousel-track { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.testimonial { padding: 18px; }
.carousel-controls { margin-top: 14px; display: flex; gap: 8px; }
.icon-btn { border: 1px solid #cfd8f2; background: #fff; border-radius: 10px; width: 38px; height: 38px; cursor: pointer; font-weight: 900; }
.faq-item { border-top: 1px solid #e2e8f5; }
.faq-q { width: 100%; text-align: left; border: 0; background: transparent; padding: 16px 4px; font-weight: 800; cursor: pointer; }
.faq-a { display: none; padding: 0 4px 16px; color: var(--muted); }
.faq-item.open .faq-a { display: block; }
.footer { margin-top: 50px; padding: 32px 0; border-top: 1px solid #e2e8f5; color: #52607d; }
.reveal { opacity: 0; transform: translateY(16px); transition: .55s ease; }
.reveal.in { opacity: 1; transform: translateY(0); }
@media (max-width: 1024px){ .hero-grid,.grid-4,.grid-3,.pricing,.logo-grid,.stats,.carousel-track{grid-template-columns:repeat(2,1fr);} }
@media (max-width: 760px){ .nav{flex-wrap:wrap;} .hero-grid,.grid-4,.grid-3,.pricing,.logo-grid,.stats,.carousel-track{grid-template-columns:1fr;} .section{padding:56px 0;} h1{font-size:2.2rem;} }
EOF

cat > /app/output/app.js <<'EOF'
const $ = (s, c=document) => c.querySelector(s);
const $$ = (s, c=document) => [...c.querySelectorAll(s)];

$$('.tab-switch').forEach(sw=>{
  const buttons = $$('button', sw);
  const target = sw.dataset.target;
  const wrap = document.getElementById(target);
  const views = $$('.preview', wrap);
  buttons.forEach(btn=>btn.addEventListener('click', ()=>{
    buttons.forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    views.forEach(v=>v.classList.add('hidden'));
    $('#' + btn.dataset.view, wrap).classList.remove('hidden');
  }));
});

$$('[data-tab-group]').forEach(group=>{
  const name = group.dataset.tabGroup;
  const btns = $$(`[data-tab-btn="${name}"]`);
  const panels = $$(`[data-tab-panel="${name}"]`);
  btns.forEach(btn=>btn.addEventListener('click', ()=>{
    btns.forEach(b=>b.classList.remove('active'));
    panels.forEach(p=>p.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById(btn.dataset.target).classList.add('active');
  }));
});

$$('[data-carousel]').forEach(car=>{
  const slides = $$('.testimonial', car);
  let i = 0;
  const render = () => slides.forEach((s,idx)=> s.style.display = idx >= i && idx < i+3 ? 'block' : 'none');
  render();
  $('.prev', car)?.addEventListener('click', ()=>{ i = (i-1+slides.length)%slides.length; render(); });
  $('.next', car)?.addEventListener('click', ()=>{ i = (i+1)%slides.length; render(); });
});

$$('.faq-item').forEach(item=>{
  $('.faq-q', item).addEventListener('click', ()=>{
    const container = item.parentElement;
    $$('.faq-item', container).forEach(el=>{ if(el!==item) el.classList.remove('open'); });
    item.classList.toggle('open');
  });
});

$$('[data-accordion-toggle]').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    const p = document.getElementById(btn.dataset.accordionToggle);
    const hidden = p.style.display === 'none';
    p.style.display = hidden ? 'block' : 'none';
  });
});

const io = new IntersectionObserver((entries)=>{
  entries.forEach(e=> e.isIntersecting && e.target.classList.add('in'));
}, {threshold: .12});
$$('.reveal').forEach(el=>io.observe(el));
EOF

